target.css:
:root {
  --ink: #243a35;
  --muted: #71827b;
  --paper: #fffefa;
  --line: #d8e5dc;
  --leaf: #287a58;
  --leaf-pale: #e5f3e9;
  --sun: #e6a62d;
  --sun-pale: #fff3d6;
}

.route-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-head,
.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.title-group,
.details {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.route-card h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.state {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--leaf-pale);
  color: var(--leaf);
  font-size: 12px;
  font-weight: 700;
}

.route-main {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 14px;
  margin: 15px 0;
}

.route-mark {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0;
  border-radius: 14px;
  background: var(--sun-pale);
}

.route-mark span {
  font-size: 28px;
}

.route-mark figcaption {
  margin-top: 3px;
  color: var(--sun);
  font-size: 11px;
  font-weight: 800;
}

.schedule {
  margin: 1px 0 10px;
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
}

.facts {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
}

.facts li {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 2px;
}

.facts li + li {
  border-left: 1px solid var(--line);
  padding-left: 12px;
}

.facts strong {
  font-size: 14px;
}

.facts span {
  color: var(--muted);
  font-size: 11px;
}

.card-foot {
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.card-foot p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.card-foot strong {
  color: var(--ink);
}

.action {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border: 0;
  border-radius: 9px;
  background: var(--leaf);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

.action span {
  font-size: 15px;
  line-height: 0;
}

